 "content": "def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker_colors = {v for row in grid for v in row if v != bg}
    # The marker color identifies the endpoints; fill the straight gaps between
    # consecutive endpoints in each row and column with the task's fill color.
    marker = next(iter(marker_colors))
    h, w = len(grid), len(grid[0])
    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 3
